298:INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (101, 'REF-01029', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'ES', NULL, 'numerical', '8%', '% longitudinal slope: <=10% for ramps under 3 m, <=8% for ramps of 3-10 m', 'Rampas de menos de 3 m. pendiente máxima 10%. Rampas de entre 3 y 10 m. pendiente máxima 8%.', 'Metodología p. 24, Pendientes longitudinales máximas', NULL, 'untraced', 'REF-01029', NULL, 'stated_unmeasured', 'not_device_scoped', NULL, NULL, 0, NULL, 'section', NULL, NULL, 'p. 24', 'Pendientes longitudinales máximas', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'preliminary', NULL, 'AN ECHO, NOT AN INDEPENDENT FIGURE: it reproduces the figures of Orden VIV/561/2010 art. 14.1 b) (retrieved from BOE this session, BOE-A-2010-4057), in force when the Metodología was written (December 2018) and DEROGATED on 2022-01-02 by Orden TMA/851/2021 (REF-01028). Spain''s current urban-space rule keeps 10%/8% but caps the 8% tier at 9 m. The same page states a 2% maximum cross-slope: a different axis, not extracted. || 2026-10-01 root_type SET committee_assertion -> untraced (ADVERSARIAL-PASS REPAIR (F13). The 10%/8% tiers trace to Orden VIV/561/2010 art. 14.1 b), which was retrieved but NOT admitted (derogated 2022-01-02): the root is not held in this corpus, so ''untraced'' (batch-19 precedent), not a self-rooted committee assertion. (v_value_independence ignores committee_assertion and untraced rows alike; this keeps the typed column consistent with the note.))', '2026-10-01 03:00', 'session_2026-10-01-research-batch-23', '2026-10-01 03:39', 'session_2026-10-01-research-batch-23', 'claim', '<=');
